// Bahromjon Yo'ldoshev imzosi — base64 PNG (transparent, 600px)
window.__WD_SIGNATURE__ = "data:image/png;base64,";


// Image obyektini preload qilamiz — mkCertTex (3D natijalar devori) uchun
(function(){
  if (typeof Image !== 'undefined' && window.__WD_SIGNATURE__){
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.src = window.__WD_SIGNATURE__;
    window.__WD_SIG_IMG__ = img;
  }
})();
